### Updated `RivalRadarPlugin.java`

```java
package com.itmeansbigmountain.rivalradar;

import com.google.inject.Provides;
import com.itmeansbigmountain.osrsapi.WOMApiClient;
import com.itmeansbigmountain.osrsapi.TempleApiClient;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.Notifier;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.ui.overlay.components.Component;
import net.runelite.client.ui.overlay.util.SwingUtil;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.components.ColorRgb;

import java.awt.*;
import java.time.Instant;
import java.time.Duration;
import java.util.*;
import java.util.regex.Pattern;
import java.util.concurrent.atomic.AtomicReference;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * Rival Radar – compares local player XP with rivals using WiseOldMan and TempleOSRS APIs.
 */
@PluginDescriptor(
        name = "Rival Radar",
        description = "Compares XP gains with rival players using TWOM and TempleOSRS APIs",
        tags = {"xp", "rival", "comparison", "osrs"}
)
@Slf4j
public class RivalRadarPlugin extends Plugin {

    @Inject private Client client;
    @Inject private RivalRadarConfig config;
    @Inject private OverlayManager overlayManager;
    @Inject private Notifier notifier;

    /** Cache of rival player names → 7‑day XP */
    private final Map<String, Double> rivalXPCache = new ConcurrentHashMap<>();

    /** When we last refreshed the rival list */
    private Instant lastRefresh = Instant.EPOCH;

    /* --------------------------------------------------------------------- */
    /*  CONFIG PROVIDER                                                       */
    /* --------------------------------------------------------------------- */
    @Provides
    RivalRadarConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(RivalRadarConfig.class);
    }

    /* --------------------------------------------------------------------- */
    /*  PLUGIN LIFECYCLE                                                       */
    /* --------------------------------------------------------------------- */
    @Override
    protected void startUp() throws Exception {
        log.info("Rival Radar starting up…");
        refreshRivals();
        if (config.showOverlay()) {
            overlayManager.add(new RivalRadarOverlay(this));
        }
    }

    @Override
    protected void shutDown() throws Exception {
        log.info("Rival Radar shutting down…");
        overlayManager.removeIf(RivalRadarOverlay.class::isInstance);
        rivalXPCache.clear();
    }

    /* --------------------------------------------------------------------- */
    /*  EVENT LISTENERS                                                       */
    /* --------------------------------------------------------------------- */
    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE) {
            return;
        }

        String msg = event.getMessage().replaceAll("<[^>]*>", "").toLowerCase();

        /*  !rival <name>  –  manual trigger for a single rival comparison  */
        if (msg.startsWith("!rival ")) {
            String rivalName = msg.substring(7).trim();
            if (!rivalName.isEmpty()) {
                compareWithRival(rivalName);
            }
        }
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        // Auto‑refresh based on the user‑defined interval
        if (Duration.between(lastRefresh, Instant.now()).getSeconds() >= config.refreshInterval()) {
            refreshRivals();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  CORE LOGIC                                                            */
    /* --------------------------------------------------------------------- */

    /** Refreshes the list of rival XP values according to the configured interval. */
    private void refreshRivals() {
        String rivalsCsv = config.rivalNames();
        if (rivalsCsv == null || rivalsCsv.trim().isEmpty()) {
            return;
        }

        String[] names = rivalsCsv.split(",");
        for (String name : names) {
            name = name.trim();
            if (name.isEmpty()) continue;
            try {
                double xp = get7DayXP(name.trim());
                rivalXPCache.put(name, xp);
            } catch (Exception e) {
                log.warn("Failed to fetch XP for rival '{}': {}", name, e.getMessage());
            }
        }

        lastRefresh = Instant.now();
        log.info("Updated rival XP cache: {}", rivalXPCache.keySet());
    }

    /** Fetch the local player’s 7‑day XP and cache it locally. */
    private double getLocalPlayerXP() {
        try {
            String myName = getLocalPlayerName();
            return get7DayXP(myName);
        } catch (Exception e) {
            log.error("Failed to compute local player XP: {}", e.getMessage());
            return 0;
        }
    }

    /** Returns a map of rival name → cached XP value. */
    public Map<String, Double> getRivalXPCache() {
        return rivalXPCache;
    }

    /** Simple accessor used by the overlay for display purposes. */
    public String getLocalPlayerName() {
        Player local = client.getLocalPlayer();
        return (local != null) ? local.getName() : "Unnamed";
    }

    /** Calculates the *local* player’s 7‑day XP by averaging the two downstream API calls. */
    private double calculateXP() {
        try {
            double womXP = WOMApiClient.getPlayerGains(getLocalPlayerName());
            double templeXP = 0;
            try {
                String templeResp = TempleApiClient.getPlayerGains(getLocalPlayerName());
                templeXP = parseXPFromResponse(templeResp);
            } catch (Exception ignored) {
                // Temple API may be temporarily unavailable – fall back to WOMAPI only
            }
            return (womXP + templeXP) / 2.0;
        } catch (Exception e) {
            log.error("Error obtaining local player XP: {}", e.getMessage());
            return 0;
        }
    }

    /** Public helper – returns the local player’s name. */
    public String getLocalPlayerName() {
        return getLocalPlayerNameInternal();
    }

    /** Private convenience – extracts a numeric XP value from an API response string. */
    private static final Pattern XP_PATTERN = Pattern.compile("(?:total_gained|xp)\\s*[:=]\\s*(\\d+)", Pattern.CASE_INSENSITIVE);

    private double parseXPFromResponse(String response) {
        Matcher m = XP_PATTERN.matcher(response);
        if (m.find()) {
            try {
                return Double.parseDouble(m.group(1));
            } catch (NumberFormatException ignored) {
            }
        }
        return 0;
    }

    /** Retrieve a player’s 7‑day XP from the combined APIs. */
    private double get7DayXP(String playerName) throws Exception {
        try {
            // Primary source – WiseOldMan
            String womResp = WOMApiClient.getPlayerGains(playerName);
            double womXP = parseXPFromResponse(womResp);

            // Secondary source – TempleOSRS (optional fallback)
            double templeXP = 0;
            try {
                String templeResp = TempleApiClient.getPlayerGains(playerName);
                templeXP = parseXPFromResponse(templeResp);
            } catch (Exception ignored) {
                // not fatal – we still have the WOMAPI value
            }

            // Return the average if both succeeded; otherwise whichever succeeded
            return (womXP + templeXP) / 2.0;
        } catch (Exception e) {
            log.warn("Failed to get XP for {}: {}", playerName, e.getMessage());
            return 0;
        }
    }

    /** Compare the local player’s XP with a specific rival and fire a notification if the delta exceeds the threshold. */
    private void compareWithRival(String rivalName) {
        try {
            double rivalXP = get7DayXP(rivalName);
            double localXP = getLocalPlayerXP();

            double delta = rivalXP - localXP;
            double absDelta = Math.abs(delta);

            if (absDelta > config.notificationThreshold()) {
                String direction = delta > 0 ? "ahead of you" : "behind you";
                String msg = String.format("%s is %d XP %s!",
                        rivalName,
                        (int)Math.round(absDelta),
                        direction);
                notifier.notify(msg);
            }

            // Force overlay refresh so the UI updates immediately
            if (config.showOverlay()) {
                overlayManager.removeAll();
                overlayManager.add(new RivalRadarOverlay(this));
            }

        } catch (Exception e) {
            log.error("Error comparing with rival '{}': {}", rivalName, e.getMessage());
            notifier.notify("Failed to fetch rival data: " + e.getMessage());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  OVERLAY                                                               */
    /* --------------------------------------------------------------------- */
    /** Simple overlay that prints the local player and rival XP values. */
    public static class RivalRadarOverlay extends Overlay {

        private final RivalRadarPlugin plugin;
        private final PanelComponent panel = new PanelComponent();

        @Inject
        public RivalRadarOverlay(RivalRadarPlugin plugin) {
            this.plugin = plugin;
            setPosition(OverlayPosition.TOP_LEFT);
            setLayer(OverlayLayer.ABOVE_WIDGETS);
            setPriority(Overlay.PRIORITY_LOW);
        }

        @Override
        public Dimension render(Graphics2D graphics) {
            panel.getChildren().clear();

            // Local player line
            String localName = plugin.getLocalPlayerName();
            double localXP = plugin.getLocalPlayerXP();
            panel.getChildren().add(TitleComponent.builder()
                    .text("You")
                    .style(ColorRgb.CYAN)
                    .build());

            panel.getChildren().add(LineComponent.builder()
                    .left(localName)
                    .right(String.format("%.0f XP", localXP))
                    .style(ColorRgb.WHITE)
                    .build());

            // Rival entries
            for (Map.Entry<String, Double> entry : plugin.getRivalXPCache().entrySet()) {
                String rivalName = entry.getKey();
                double rivalXP = entry.getValue();
                double delta = rivalXP - plugin.getLocalPlayerXP();
                String deltaStr = String.format("%+.0f", delta);
                Color color = (delta >= 0) ? ColorRgb.GREEN : ColorRgb.RED;

                panel.getChildren().add(LineComponent.builder()
                        .left(rivalName)
                        .right(deltaStr + " XP")
                        .style(color)
                        .build());
            }

            return panel.render(graphics);
        }
    }
}
